package com.andye.warmod.phalanx;import com.andye.warmod.warhead.WarheadPayloadType;import java.util.*;import net.minecraft.world.phys.Vec3;
public final class PhalanxTargetSelector{private PhalanxTargetSelector(){}public static Optional<PhalanxTargetSnapshot> select(Vec3 centre,Vec3 muzzle,List<PhalanxTargetSnapshot> candidates){return candidates.stream().filter(t->valid(centre,muzzle,t)).min(Comparator.comparingDouble(PhalanxTargetSnapshot::ticksToImpact).thenComparingDouble(t->horizontal(centre,t.predictedImpact())).thenComparingInt(t->t.payloadType().orElse(null)==WarheadPayloadType.NUCLEAR?0:1).thenComparingInt(t->t.kind()==PhalanxTargetKind.CLUSTER_SUBMUNITION?0:t.kind()==PhalanxTargetKind.MK_I_FALLBACK?2:1).thenComparingDouble(t->centre.distanceToSqr(t.position())).thenComparing(t->t.targetId().toString()));}public static boolean valid(Vec3 centre,Vec3 muzzle,PhalanxTargetSnapshot t){if(t==null||!t.position().isFinite()||!t.velocity().isFinite()||!t.predictedImpact().isFinite())return false;if(horizontal(centre,t.predictedImpact())>PhalanxConstants.PROTECTED_RADIUS_BLOCKS)return false;if(muzzle.distanceTo(t.position())>PhalanxConstants.MAX_ENGAGEMENT_RANGE_BLOCKS)return false;double h=Math.hypot(t.position().x-muzzle.x,t.position().z-muzzle.z),e=Math.toDegrees(Math.atan2(t.position().y-muzzle.y,h));return e>=PhalanxConstants.MIN_ELEVATION_DEGREES&&e<=PhalanxConstants.MAX_ELEVATION_DEGREES;}public static double horizontal(Vec3 a,Vec3 b){return Math.hypot(a.x-b.x,a.z-b.z);}}
